use std::collections::HashMap
use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut m: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().collect()
        if p.len() < 2 {
            continue
        }
        let cmd = p[0]
        if cmd == "open" && p.len() >= 3 {
            let amt: int = p[2].parse::<int>().unwrap_or(-1)
            if amt < 0 {
                println("error: invalid amount")
            } else if m.contains_key(p[1]) {
                println("error: duplicate account")
            } else {
                m.insert(p[1], amt)
                println("ok")
            }
        } else if cmd == "deposit" && p.len() >= 3 {
            let amt: int = p[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !m.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else {
                let cur: int = m[p[1]]
                m.insert(p[1], cur + amt)
                println("ok")
            }
        } else if cmd == "withdraw" && p.len() >= 3 {
            let amt: int = p[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !m.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else {
                let cur: int = m[p[1]]
                if cur < amt {
                    println("error: insufficient funds")
                } else {
                    m.insert(p[1], cur - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && p.len() >= 4 {
            let amt: int = p[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !m.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else if !m.contains_key(p[2]) {
                println("error: unknown account ${p[2]}")
            } else if p[1] == p[2] {
                println("error: same account")
            } else {
                let a: int = m[p[1]]
                let b: int = m[p[2]]
                if a < amt {
                    println("error: insufficient funds")
                } else {
                    m.insert(p[1], a - amt)
                    m.insert(p[2], b + amt)
                    println("ok")
                }
            }
        } else if cmd == "balance" {
            if !m.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else {
                let cur: int = m[p[1]]
                println("${cur}")
            }
        }
    }
    let mut keys: Vec<string> = m.keys().collect()
    keys.sort()
    for k in keys {
        let v: int = m[k]
        println("${k} ${v}")
    }
}

